 static byte[] draw(Booted b){org.lwjgl.opengl.GL11.glViewport(0,0,320,224);org.lwjgl.opengl.GL11.glClearColor(1,0,1,1);org.lwjgl.opengl.GL11.glClear(org.lwjgl.opengl.GL11.GL_COLOR_BUFFER_BIT|org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT);b.module.gameplayFrameController().drawOverlay();org.lwjgl.opengl.GL11.glFinish();var data=org.lwjgl.BufferUtils.createByteBuffer(320*224*4);org.lwjgl.opengl.GL11.glReadPixels(0,0,320,224,org.lwjgl.opengl.GL11.GL_RGBA,org.lwjgl.opengl.GL11.GL_UNSIGNED_BYTE,data);assertEquals(org.lwjgl.opengl.GL11.GL_NO_ERROR,org.lwjgl.opengl.GL11.glGetError());byte[] result=new byte[data.remaining()];data.get(result);return result;}
 /** Optional evidence from the actual selected renderer; never loaded back as an oracle/asset. */
 static void exportPicture(Booted b,byte[] rgba,String name)throws Exception{
  String raw=System.getProperty("soniccd.r31.capture.dir");if(raw==null)return;
  Path root=Path.of(Objects.requireNonNull(System.getenv("SONICCD_ENGINE_CAPTURE_ROOT"))).toRealPath();
  assertEquals(Path.of(System.getProperty("user.home"),"Downloads","Sonic-CD","captures","engine").toRealPath(),root);
  Path directory=Path.of(raw);assertTrue(directory.isAbsolute());assertEquals(directory,directory.toRealPath());assertTrue(directory.startsWith(root)&&!directory.equals(root));
  var image=new java.awt.image.BufferedImage(320,224,java.awt.image.BufferedImage.TYPE_INT_ARGB);
  for(int y=0;y<224;y++)for(int x=0;x<320;x++){int offset=((223-y)*320+x)*4;image.setRGB(x,y,((rgba[offset+3]&255)<<24)|((rgba[offset]&255)<<16)|((rgba[offset+1]&255)<<8)|(rgba[offset+2]&255));}
  try(var output=Files.newOutputStream(directory.resolve(name+".png"),StandardOpenOption.CREATE_NEW)){assertTrue(javax.imageio.ImageIO.write(image,"png",output));}
  var core=b.module.r31LoadingVisit();var frame=b.module.requirePlayerFrame();var host=b.module.r31WorldHost();
  Files.writeString(directory.resolve(name+".txt"),"ENGINE selected R31 USA; constructed historical profile/execution platform; genuine Boot/FULL/loading/ordinary/render ingress\n"+
    "phase="+core.state().phase()+"; levelFrames="+frame.environment().globals().levelFrames()+"; routine="+frame.state().motion().routine()+"; VInt="+frame.vIntClock()+"; generation="+b.mode.getLevelManager().getCompletedProductionLoadGeneration()+"\n"+
    "asset="+((CdGameDataSource)b.mode.getWorldSession().getDataSource()).identity()+"\n"+
    "programme="+((CdGameDataSource)b.mode.getWorldSession().getDataSource()).r31aAssets().orElseThrow().identity()+"\n"+
    "rgba_sha256="+HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(rgba))+"\n"+
    "Completed CPU="+host.video().completedCpu().map(c->Integer.toString(c.spriteCount())).orElse("absent")+"; selected="+host.selected().getClass().getSimpleName()+"\n",StandardOpenOption.CREATE_NEW);
 }
