 static void ready(Booted b){for(int i=0;i<256&&b.module.r31LoadingVisit().state().phase()!=SonicCdR31aLoadingVisit.Phase.READY;i++)step(b,8);assertEquals(SonicCdR31aLoadingVisit.Phase.READY,b.module.r31LoadingVisit().state().phase());}
