 private static synchronized CdGameDataSource source()throws Exception{var root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original-USA source absent");var usa=Path.of(root).resolve("USA");assertTrue(Files.isDirectory(usa),"Configured source must exist");if(cached!=null&&root.equals(cachedRoot))return cached;List<Path> cues;try(var files=Files.list(usa)){cues=files.filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();}assertEquals(1,cues.size());cached=CdStockLaunch.prepare(cues.getFirst(),CdStockLaunch.Request.r11a());cachedRoot=root;return cached;}
